    /// <summary>这张卡有没有这个 tag（tag 名形如 <c>subtype.t34</c>）。</summary>
    public static bool Has(string cardName, string tag)
    {
        if (cardName.Length == 0 || tag.Length == 0)
        {
            return false;
        }

        foreach (string candidate in Candidates(cardName))
        {
            if (TagsByCard.TryGetValue(candidate, out string[]? tags)
                && Array.IndexOf(tags, tag) >= 0)
            {
                return true;
            }
        }

        return false;
    }

    /// <summary>
    /// 这张卡带不带**任意** tag。
    ///
    /// 用途：`getHasGameplayTag` 的 tag 实参在 IR 里可能被丢掉
    /// （`StructConst /Script/GameplayTags.GameplayTag` 被生成器压成了 `{struct:null}`），
    /// 那时只能退一步问「它是不是某种子类型」。**这不是通用正确解**，
    /// 调用点同时会把 `getHasGameplayTag<ir-tag-lost>` 记进未实现统计。
    /// </summary>
    public static bool Any(string cardName)
    {
        foreach (string candidate in Candidates(cardName))
        {
            if (TagsByCard.ContainsKey(candidate))
            {
                return true;
            }
        }

        return false;
    }

    private static IEnumerable<string> Candidates(string cardName)
    {
        yield return cardName;

        string baseName = Cards.CardDatabase.ResolveBaseName(cardName);
        if (!string.Equals(baseName, cardName, StringComparison.Ordinal))
        {
            yield return baseName;
        }
    }
